/**
 * @name XPath injection in lxml
 * @description User input used directly in XPath expressions could lead to XPath injection
 * @kind path-problem
 * @problem.severity error
 * @id py/xpath-injection
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XPathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // XPath evaluation methods in lxml
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember(["xpath", "find", "findall", "findtext"]).getACall() or
      call = API::moduleImport("lxml").getMember("html").getMember(["xpath", "find", "findall", "findtext"]).getACall()
    |
      // The XPath expression argument (usually first argument)
      sink = call.getArg(0)
    )
  }
}

module XPathFlow = TaintTracking::Global<XPathConfig>;
import XPathFlow::PathGraph

from XPathFlow::PathNode source, XPathFlow::PathNode sink
where XPathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XPath injection from $@.", source.getNode(), "user input"
